"""
FitBuddy one-click repository builder.

HOW TO USE:
  1. Save this file as setup_fitbuddy.py
  2. Run:  python setup_fitbuddy.py
  3. It creates the full FitBuddy folder (all folders + files) and can push it to GitHub.
"""
